describe('Card Decline Error Handling', () => {
  beforeEach(() => {
    cy.visit('/checkout');
  });

  it('should display error message when card is declined', () => {
    // Intercept the payment API call
    cy.intercept('POST', '/api/payment/process').as('processPayment');

    // Fill in form with valid card details
    cy.get('[data-testid="card-number-input"]').type('4111111111111111');
    cy.get('[data-testid="expiry-date-input"]').type('12/25');
    cy.get('[data-testid="cvv-input"]').type('123');
    cy.get('[data-testid="card-holder-name-input"]').type('John Doe');

    // Click pay button
    cy.get('[data-testid="pay-button"]').click();

    // Wait for API response
    cy.wait('@processPayment').then((interception) => {
      expect(interception.response.statusCode).to.equal(422);
    });

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .should('contain', 'Card declined by your bank');

    // Verify error styling
    cy.get('[data-testid="error-message"]')
      .should('have.class', 'error-text');

    // Verify payment form is still visible for retry
    cy.get('[data-testid="card-number-input"]').should('be.visible');
  });

  it('should handle multiple failed payment attempts and prevent form submission', () => {
    // Intercept payment API call and mock multiple failures
    cy.intercept('POST', '/api/payment/process', {
      statusCode: 422,
      body: { error: 'Card declined' }
    }).as('processPayment1');

    cy.intercept('POST', '/api/payment/process', {
      statusCode: 422,
      body: { error: 'Card declined' }
    }).as('processPayment2');

    // Fill in form with valid card details
    cy.get('[data-testid="card-number-input"]').type('4111111111111111');
    cy.get('[data-testid="expiry-date-input"]').type('12/25');
    cy.get('[data-testid="cvv-input"]').type('123');
    cy.get('[data-testid="card-holder-name-input"]').type('John Doe');

    // First attempt
    cy.get('[data-testid="pay-button"]').click();
    cy.wait('@processPayment1');

    // Verify first error message
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .should('contain', 'Card declined by your bank');

    // Second attempt
    cy.get('[data-testid="pay-button"]').click();
    cy.wait('@processPayment2');

    // Verify second error message
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .should('contain', 'Card declined by your bank');

    // Verify retry button is available
    cy.get('[data-testid="retry-button"]').should('be.visible');

    // Verify form is not disabled after multiple failures
    cy.get('[data-testid="card-number-input"]').should('not.be.disabled');
  });
});
